import {standings,currentWeek,weekPairs,profile,projectedMean,mean,MODEL_VERSION} from './model.js';
import {parseCSV,readXlsx,historyPreview,mergeHistory,weeklyPreview,findBowler} from './imports.js';
import {cloud} from './cloud.js';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n==null?'—':(n*100).toFixed(1)+'%',fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:1});
let state,view='outlook',period=0,selectedWeek=1,query='',showSubs=false,dirty=false,revision=0,cloudReady=false,error='',pending=[],worker=null,progress=0,iterations=10000,randomSeed=202627,selectedRun=null,toastTimer;
const nav=[['outlook','Season outlook'],['players','Player ratings'],['teams','Teams & rosters'],['schedule','Schedule & results'],['imports','Import scores'],['setup','Setup & rules']];
const teamName=n=>state.teams.find(t=>t.number===n)?.name||'Team '+n;
const playerName=id=>state.bowlers.find(b=>b.id===id)?.name||'Unknown bowler';
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
function changed(){dirty=true;selectedRun=null;error='';}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function options(items,current){return items.map(([v,label])=>`<option value="${escape(v)}" ${String(v)===String(current)?'selected':''}>${escape(label)}</option>`).join('');}
function heading(kicker,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`;}
function coverage(){const regular=state.bowlers.filter(b=>state.teams.some(t=>t.players.includes(b.id)));return [regular.filter(b=>profile(state,b).priorGames>0).length,regular.length];}
function activeRun(){return selectedRun?state.runs.find(r=>r.id===selectedRun):state.runs.at(-1);}
function runFingerprint(){return JSON.stringify({teams:state.teams.map(t=>({number:t.number,players:t.players})),bowlers:state.bowlers.map(b=>({id:b.id,entering:b.entering,history:b.history})),results:state.results,adjustments:state.adjustments,thirdWinners:state.thirdWinners});}
function render(){
 const [have,total]=coverage(),w=currentWeek(state);
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">SCRATCH<br>CLASSIC<span>LEAGUE FORECAST</span></div><div class="season-tag">2026 / 2027 SEASON</div><nav aria-label="Main navigation">${nav.map(([v,label],i)=>`<button class="nav-button ${view===v?'active':''}" data-view="${v}" ${view===v?'aria-current="page"':''}><span class="nav-index">0${i+1}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot"><strong>Upstate Amusements</strong>18 teams · 7 playoff places<br><span>${have} of ${total} histories loaded</span></div></aside><main class="main"><header class="topbar"><span>UPSTATE AMUSEMENTS / <strong>2026–2027</strong></span><div class="top-actions"><span>${cloudReady?(dirty?'Unsaved changes':'Saved league loaded'):'Setup required · changes not saved'}</span><button data-action="save" ${worker?'disabled':''}>Save league</button><button data-view="setup">${cloud.email?'Account':'Sign in'}</button></div></header>${error?`<div class="notice error" role="alert">${escape(error)}</div>`:''}${({outlook:outlook,players:playersView,teams:teamsView,schedule:scheduleView,imports:importsView,setup:setupView}[view])()}<footer class="footer"><span>SCRATCH CLASSIC · ${MODEL_VERSION}</span><span>${w} of 34 weeks recorded · Championship date TBD</span></footer></main></div>`;
}
function outlook(){
 const run=activeRun(),[have,total]=coverage(),w=currentWeek(state),byTeam=Object.fromEntries((run?.teams||[]).map(t=>[t.number,t])),stale=run&&run.fingerprint!==runFingerprint();
 const rows=standings(state,period),best=run?.teams.slice().sort((a,b)=>b.champion-a.champion)[0];
 return heading('The season, in perspective','Season outlook','Playoff paths and championship chances, one week at a time.',`<span class="badge amber">PROVISIONAL MODEL</span>`)+
 `<div class="notice">${have} of ${total} regular-player histories loaded. Missing histories use entering averages and an assumed 30-pin spread. ${w===0?'No current-season results have been imported; all 34 weeks remain unplayed in the model.':''} <button class="text-button" data-view="imports">Add scoring history</button></div>`+
 `<section class="panel"><div class="panel-body"><div class="controls"><label>Season simulations<input id="iterations" type="number" min="1" max="100000" step="1" value="${iterations}" ${worker?'disabled':''}></label><label>Random seed<input id="random-seed" type="number" min="0" max="4294967295" step="1" value="${randomSeed}" ${worker?'disabled':''}></label><div class="spacer"></div><span class="fine muted">${Object.values(state.adjustments).filter(a=>a.delta).length} player adjustments · ${34-w} weeks to simulate</span><button class="primary" data-action="simulate" ${worker?'disabled':''}>${worker?'Simulating…':'Run simulations'}</button>${worker?'<button data-action="cancel-simulation">Cancel</button>':''}</div>${worker?`<div class="progress" role="progressbar" aria-label="Simulation progress" aria-valuenow="${Math.round(progress*100)}" aria-valuemin="0" aria-valuemax="100"><div style="width:${progress*100}%"></div></div>`:''}</div></section>`+
 (stale?'<div class="notice">These odds were calculated before the latest changes. Run simulations to update them.</div>':'')+
 `<div class="metrics"><div class="metric"><div class="label">PLAYOFF PLACES</div><div class="value">7 <span class="muted">/ 18</span></div><div class="foot">Third winners + wild cards</div></div><div class="metric"><div class="label">SEASON PROGRESS</div><div class="value">${w} <span class="muted">/ 34</span></div><div class="foot">Completed weeks stay fixed</div></div><div class="metric"><div class="label">CHAMPIONSHIP FAVORITE</div><div class="value">${best?pct(best.champion):'—'}</div><div class="foot">${best?escape(teamName(best.number)):'Run the first simulation'}</div></div><div class="metric"><div class="label">LATEST RUN</div><div class="value">${run?fmt(run.iterations):'—'}</div><div class="foot">${run?`Through Week ${run.completedWeeks} · ${new Date(run.createdAt).toLocaleDateString()}`:'Ready when you are'}</div></div></div>`+
 panel('Standings & projections',`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Team</th><th class="num">${period?'Third':'Season'} pts</th><th class="num">Team avg</th><th class="num">Projected season pts</th><th class="num">Make playoffs</th><th class="num">Win league</th></tr></thead><tbody>${rows.map((t,i)=>{const p=byTeam[t.number];return `<tr><td class="muted">${w?i+1:'—'}</td><td><div class="team-cell"><span class="team-no">${t.number}</span><div class="team-name">${escape(t.name)}<span class="subline">${state.teams.find(x=>x.number===t.number).players.map(id=>escape(playerName(id))).join(' · ')}</span></div></div></td><td class="num">${fmt(t.points)}</td><td class="num">${t.games?fmt(t.average):'—'}</td><td class="num">${p?fmt(p.points):'—'}</td><td class="num">${prob(p?.playoffs)}</td><td class="num">${prob(p?.champion,true)}</td></tr>`;}).join('')}</tbody></table></div>`, `<div class="tab-pills">${[0,1,2,3].map(p=>`<button data-period="${p}" class="${p===period?'active':''}">${p?'Third '+p:'Overall'}</button>`).join('')}</div>`)+
 `<div class="split">${panel('Simulation history',state.runs.length?state.runs.slice().reverse().map(r=>`<div class="history-run"><div><strong>${fmt(r.iterations)} simulations</strong><span class="subline">${new Date(r.createdAt).toLocaleString()} · through Week ${r.completedWeeks} · seed ${r.seed}</span></div><button data-run="${r.id}">View</button></div>`).join(''):'<div class="empty"><h3>No saved runs yet</h3><p>Your baseline and adjusted scenarios will appear here.</p></div>')}${panel('How to read these odds',`<div class="panel-body stack"><p class="fine">A playoff percentage counts how often a team reaches the seven-team field. Championship chances include the entire stepladder and the four-game final.</p><p class="fine muted">${run?`At ${fmt(run.iterations)} runs, simulation noise is at most approximately ±${(98/Math.sqrt(run.iterations)).toFixed(1)} percentage points at 95% confidence. `:''}Uncertainty in player ability is additional. This first model has not been backtested.</p><button data-view="setup">View rules & assumptions</button></div>`)}</div>`;
}
function prob(n,gold=false){return n==null?'<span class="muted">—</span>':`<div class="prob"><div class="track"><div class="fill ${gold?'gold':''}" style="width:${n*100}%"></div></div><span>${pct(n)}</span></div>`;}
function playersView(){
 const rows=state.bowlers.filter(b=>(showSubs||b.team)&&`${b.name} ${b.sourceName}`.toLowerCase().includes(query.toLowerCase())).map(b=>({b,p:profile(state,b)})).sort((a,b)=>b.p.mean-a.p.mean);
 return heading('The model starts with the bowler','Player ratings','Review scoring history and set gradual improvements or declines.')+
 panel('Player projections',`<div class="table-wrap"><table><thead><tr><th>Bowler</th><th class="num">Entering</th><th class="num">History games</th><th class="num">This season</th><th class="num">Model avg</th><th class="num">Week 34 avg</th><th>Adjustment</th></tr></thead><tbody>${rows.map(({b,p})=>{const a=state.adjustments[b.id];return `<tr><td><button class="text-button" data-player="${b.id}">${escape(b.name)}</button><span class="subline">${b.team?`Team ${b.team} · ${escape(teamName(b.team))}`:'Substitute'} ${p.provisional?'· entering-average estimate':''}</span></td><td class="num">${b.entering??'—'}</td><td class="num">${p.priorGames}</td><td class="num">${p.currentGames}</td><td class="num">${p.mean.toFixed(1)}</td><td class="num">${projectedMean(p,a,34).toFixed(1)}</td><td><button data-player="${b.id}">${a?.delta?`${a.delta>0?'+':''}${a.delta} pins · W${a.start}–${a.end}`:'Adjust player'}</button></td></tr>`;}).join('')}</tbody></table></div>`, `<div class="player-tools"><label class="sr-only" for="player-search">Search bowlers</label><input id="player-search" placeholder="Find a bowler…" value="${escape(query)}"><label class="row"><input type="checkbox" id="show-subs" ${showSubs?'checked':''}> Include substitutes</label></div>`);
}
function teamsView(){return heading('Stable numbers, editable names','Teams & rosters','Sponsor names can change. Team identity and results stay connected.')+`<div class="team-grid">${state.teams.map(t=>`<section class="team-card"><h3><span class="team-no">${t.number}</span> Team ${t.number}</h3><label>Team name<input class="team-edit" data-team-name="${t.number}" value="${escape(t.name)}" maxlength="100"></label>${t.players.map(id=>{const b=state.bowlers.find(x=>x.id===id);return `<div class="roster-player"><button class="text-button" data-player="${id}">${escape(b.name)}</button><span class="muted">${profile(state,b).mean.toFixed(1)}</span></div>`;}).join('')}<div class="roster-player"><strong>Projected team average</strong><strong>${t.players.reduce((s,id)=>s+profile(state,state.bowlers.find(b=>b.id===id)).mean,0).toFixed(1)}</strong></div></section>`).join('')}</div><div class="notice">Team 17’s regulars are James Bianchi, Mark Edwards, and T.J. Lyon. Joe Renaldi is listed as a substitute. Actual weekly imports can record substitutes; future simulations currently assume each regular lineup is available.</div>`;}
function scheduleView(){const row=state.schedule.find(s=>s.week===selectedWeek),result=state.results.find(r=>r.week===selectedWeek),future=selectedWeek>currentWeek(state),dynamic=row.kind!=='regular';const pairs=result?result.matches.map(m=>[m.teamA,m.teamB]):dynamic&&future?[]:weekPairs(state,selectedWeek);
 return heading('Every week counts','Schedule & results','Actual results stay fixed. Position-round opponents depend on standings.')+panel(`Week ${selectedWeek} · ${new Date(row.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}`,`<div class="panel-body">${dynamic&&future?'<div class="empty"><h3>Position round</h3><p>Pairings will be calculated from '+(selectedWeek===34?'year-to-date':'this third’s')+' points immediately before this week. Ties use team average.</p></div>':`<div class="schedule-grid">${pairs.map(([a,b])=>{const m=result?.matches.find(m=>m.teamA===a&&m.teamB===b);return `<div class="match"><small>${m?'RECORDED RESULT':'SCHEDULED MATCH'}</small><div class="team"><span><b>${a}</b> &nbsp;${escape(teamName(a))}</span><strong>${m?m.a.reduce((s,x)=>s+x,0):''}</strong></div><div class="team"><span><b>${b}</b> &nbsp;${escape(teamName(b))}</span><strong>${m?m.b.reduce((s,x)=>s+x,0):''}</strong></div>${m?`<small>Games: ${m.a.join(' / ')} vs ${m.b.join(' / ')}</small>`:''}</div>`;}).join('')}</div>`}</div>`,`<label class="row">Week<select id="schedule-week">${options(state.schedule.map(s=>[s.week,`Week ${s.week}${s.kind!=='regular'?' · Position round':''}`]),selectedWeek)}</select></label>`)+
 panel('Playoff path',`<div class="panel-body rule-list"><div><strong>Week 35 · Early</strong><span>No. 7 vs No. 4 · No. 6 vs No. 5<br>Three-game total pins</span></div><div><strong>Week 35 · Late</strong><span>Early winners face each other · three games</span></div><div><strong>Week 36 · Early</strong><span>Wild-card winner vs No. 3 · three games</span></div><div><strong>Week 36 · Late</strong><span>Winner vs No. 2 · three games</span></div><div><strong>Championship · TBD</strong><span>Winner vs No. 1 · four games across two lane pairs</span></div></div>`)+
 (state.results.length?`<div class="actions"><button data-action="undo-week" class="danger">Remove latest imported week (${currentWeek(state)})</button><span class="fine muted">Use this to correct and reimport the most recent week.</span></div>`:'');}
function importsView(){return heading('From scores to projections','Import scores','Review every file before adding it to the league.')+`<div class="grid-two">${panel('Bowler history',`<div class="panel-body"><p class="fine muted">Excel (.xlsx) or CSV. Keep Date, Week, Gm1, Gm2, Gm3, and any Gm4. One bowler per sheet.</p><label class="dropzone" id="history-drop"><strong>Drop history files here</strong><span>or choose files · up to 10 MB each</span><input id="history-files" type="file" accept=".xlsx,.csv" multiple></label></div>`)}${panel('Weekly league results',`<div class="panel-body"><p class="fine muted">One CSV for the full week: three bowler rows per team. Use team numbers, with actual or blind scores marked.</p><label class="dropzone" id="weekly-drop"><strong>Import Week ${currentWeek(state)+1}</strong><span>54 bowler rows · 18 teams · 3 games</span><input id="weekly-file" type="file" accept=".csv"></label><button data-action="weekly-template" style="margin-top:1rem">Download CSV template</button></div>`)}</div>`+
 pending.map((item,i)=>{if(item.type==='weekly')return `<section class="import-card"><h3>${escape(item.filename)}</h3>${item.preview.errors.length?`<ul>${item.preview.errors.map(x=>`<li>Row ${x.line}: ${escape(x.message)}</li>`).join('')}</ul>`:`<p>${item.preview.entries} bowler rows matched to Week ${item.preview.result.week}. All nine matchups are complete.</p>`}<div class="actions"><button class="primary" data-import-week="${i}" ${item.preview.errors.length?'disabled':''}>Import week</button><button data-dismiss-import="${i}">Dismiss</button></div></section>`;
 const p=previewHistory(item);return `<section class="import-card"><h3>${escape(item.filename)} <span class="muted">/ ${escape(item.sheet)}</span></h3><div class="controls" style="margin:.8rem 0"><label>Bowler<select data-import-bowler="${i}">${options([['','Choose bowler…'],...state.bowlers.map(b=>[b.id,b.name])],item.bowlerId)}</select></label><label>Season<input data-import-season="${i}" value="${escape(item.season)}" pattern="[0-9]{4}-[0-9]{4}"></label></div><p class="fine">${p.sessions.length} sessions · ${p.sessions.reduce((s,h)=>s+h.scores.length,0)} games · ${p.skipped} summary/absence rows skipped</p>${p.issues.length?`<ul>${p.issues.map(x=>`<li>Row ${x.line}: ${escape(x.message)}${x.message.startsWith('Series ')?`<label>Missing fourth game (if applicable)<input type="number" min="0" max="300" data-fourth-import="${i}" data-fourth-row="${x.line}" placeholder="Score"></label>`:''}</li>`).join('')}</ul>`:''}<div class="actions"><button class="primary" data-import-history="${i}" ${!item.bowlerId||p.issues.length?'disabled':''}>Import history</button><button data-dismiss-import="${i}">Dismiss</button></div></section>`;}).join('')+
 panel('Import activity',state.imports.length?state.imports.slice().reverse().map(x=>`<div class="history-run"><div><strong>${escape(x.filename)}</strong><span class="subline">${escape(x.description)}</span></div><span class="fine muted">${new Date(x.at).toLocaleDateString()}</span></div>`).join(''):'<div class="empty"><h3>Ready for the rest of the histories</h3><p>Individual scoring histories are kept out of the public code. Repeated records are skipped; conflicting scores are flagged.</p></div>');}
function previewHistory(item){const rows=structuredClone(item.rows);if(item.corrections){let g4=rows[0].findIndex(h=>String(h).toLowerCase()==='gm4');if(g4<0){g4=rows[0].length;rows[0].push('Gm4');}for(const [line,value] of Object.entries(item.corrections))if(value!=='')rows[Number(line)-1][g4]=Number(value);}return historyPreview(rows,item.season,item.filename);}
function setupView(){return heading('League administration','Setup & rules','Connect saved league data and review the assumptions behind the forecast.')+
 `<div class="split">${panel(cloud.email?'Your account':'Sign in to save changes',`<div class="panel-body stack">${cloud.email?`<p>Signed in as <strong>${escape(cloud.email)}</strong></p><div class="actions"><button data-action="reload-cloud">Load saved league</button><button data-action="logout">Sign out</button></div>`:`<form id="login-form" class="stack"><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">Sign in</button></form>`}<p class="fine muted">${cloudReady?'Saving stores the full league workspace in Supabase.':'Until database setup is complete, changes remain an unsaved draft in this tab. Export a copy before closing.'}</p><div class="actions"><button data-action="export">Export league backup</button><label>Restore backup<input id="restore-backup" type="file" accept=".json"></label></div></div>`)}${panel('One-time Supabase setup',`<div class="panel-body"><ol class="steps fine"><li>Open <a href="https://supabase.com/dashboard/project/dnyuphrlxkbjifqnnydg/sql/new" target="_blank" rel="noopener">Supabase SQL Editor</a>. Run these scripts in order: <a href="./setup/001_foundation.sql" target="_blank">001 foundation</a>, <a href="./setup/002_seed_league.sql" target="_blank">002 league seed</a>, then <a href="./setup/003_app_access.sql" target="_blank">003 app access</a>. Run each only once.</li><li>In Authentication → Users, add your email and password as a confirmed user.</li><li>Replace the email below and run it in SQL Editor to grant your account access.</li><li>Sign in here, then choose <strong>Save league</strong> to save the initial workspace.</li></ol><pre>insert into public.app_admins(user_id)
select id from auth.users
where email = 'YOUR_EMAIL_HERE'
on conflict do nothing;</pre></div>`)}</div>`+
 panel('Confirmed competition rules',`<div class="panel-body rule-list"><div><strong>Regular season</strong><span>34 weeks. Three 11-week thirds, then an overall position round.</span></div><div><strong>Weekly points</strong><span>2 per team game + 3 for total series. Ties split points: 1 per game, 1.5 per series.</span></div><div><strong>Position rounds</strong><span>Weeks 10–11, 21–22, 32–33 use third points. Week 34 uses total points. Pair 1–2, 3–4, etc.; ties use calculated team average.</span></div><div><strong>Playoff qualification</strong><span>Seven teams: unique third winners, then remaining teams by year-to-date points. Ties for qualification use a one-game roll-off.</span></div><div><strong>Seeding</strong><span>A multiple-third winner is No. 1. Other third winners are ranked by season points, above all wild cards.</span></div><div><strong>Playoff matches</strong><span>Three-game total pins, except the four-game championship. Tied matches go to a one-game roll-off.</span></div></div>`)+
 panel('Model assumptions to review',`<div class="panel-body stack"><p class="fine">Historical scores are weighted toward recent games and anchored to entering average with 12 games of weight. Current-season scores gradually replace the prior estimate using 30 games of prior weight. Score variability is estimated from individual games and stabilized using a 30-pin fallback spread.</p><p class="fine">Each simulated session includes a shared lane-condition effect and a player-specific night effect. These initial settings are assumptions, not fitted results. Future regular lineups are assumed present. Blind scores count toward actual team results, but not player skill.</p><p class="fine">Remaining rule assumptions: position-round average uses season-to-date team pins divided by team games. If points and that average are exactly tied, team number orders the position pairing. Tied seeds and multi-team qualification ties use simulated one-game scores; the league’s precise procedures still need confirmation.</p><p class="fine">If a completed third ends tied, record the actual roll-off winner below. Otherwise each simulation resolves that unrecorded tie. The app currently forecasts the full playoffs; importing completed playoff matches will be added before playoff season.</p><div class="controls">${[1,2,3].map(n=>`<label>Third ${n} roll-off winner<select data-third-winner="${n}">${options([['','Not recorded / no override'],...state.teams.map(t=>[t.number,`${t.number} · ${t.name}`])],state.thirdWinners?.[n]||'')}</select></label>`).join('')}</div></div>`);}
function openPlayer(id){const b=state.bowlers.find(x=>x.id===id),p=profile(state,b),adj=state.adjustments[id]||{delta:0,start:Math.min(34,currentWeek(state)+1),end:34};const sessions=b.history.slice().sort((a,b)=>a.date.localeCompare(b.date)),values=sessions.map(h=>mean(h.scores));
 const points=values.map((v,i)=>`${35+i/Math.max(1,values.length-1)*595},${125-(v-140)/160*105}`).join(' ');
 $('#player-dialog').innerHTML=`<div class="panel-head"><div><div class="eyebrow">PLAYER PROJECTION</div><h2>${escape(b.name)}</h2></div><button data-action="close-player" aria-label="Close player details">Close</button></div><div class="panel-body"><div class="metrics" style="grid-template-columns:repeat(3,1fr);margin-top:0"><div><span class="fine muted">MODEL AVERAGE</span><h2>${p.mean.toFixed(1)}</h2></div><div><span class="fine muted">HISTORY GAMES</span><h2>${p.priorGames}</h2></div><div><span class="fine muted">GAME SPREAD</span><h2>${p.sd.toFixed(1)} pins</h2></div></div>${values.length?`<h3>Session averages · prior history</h3><svg class="chart" viewBox="0 0 650 150" role="img" aria-label="Historical session averages for ${escape(b.name)}"><line x1="35" y1="85" x2="630" y2="85" stroke="#d9e5e4"/><text x="3" y="89">200</text><polyline points="${points}" fill="none" stroke="#087c73" stroke-width="2.5"/><text x="35" y="145">${sessions[0].date}</text><text x="550" y="145">${sessions.at(-1).date}</text></svg>`:'<div class="notice">No game history yet. This rating starts with entering average and an assumed scoring spread.</div>'}<form id="adjustment-form" data-bowler="${id}" class="stack"><h3>Adjust expected skill</h3><p class="fine muted">Apply a gradual change to the model average. Actual scores are preserved. Equal start and end weeks apply the change immediately.</p><div class="controls"><label>Change in pins<input name="delta" type="number" min="-100" max="100" step="0.5" value="${adj.delta}" required></label><label>Start week<input name="start" type="number" min="1" max="37" value="${adj.start}" required></label><label>Reach full change<input name="end" type="number" min="1" max="37" value="${adj.end}" required></label></div><p class="fine muted">Weeks 35–36 are playoffs; Week 37 represents the undated championship for projection timing.</p><div class="actions"><button class="primary" type="submit">Apply adjustment</button><button type="button" data-reset-player="${id}">Reset to model</button></div></form>${sessions.length?`<details style="margin-top:1.5rem"><summary>View ${sessions.length} history sessions</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Games</th><th class="num">Series</th></tr></thead><tbody>${sessions.slice().reverse().map(s=>`<tr><td>${s.date}</td><td>${s.scores.join(' / ')}</td><td class="num">${s.scores.reduce((a,b)=>a+b,0)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`;$('#player-dialog').showModal();}
let saving=false;
async function save(){if(saving)return;if(!cloudReady){view='setup';render();toast('Complete setup and sign in before saving.');return;}const snapshot=structuredClone(state);saving=true;try{const next=await cloud.save(snapshot,revision);revision=next;dirty=JSON.stringify(snapshot)!==JSON.stringify(state);render();toast(dirty?'Saved. Newer edits still need saving.':'League saved to Supabase.');}catch(e){error=e.message;render();}finally{saving=false;}}
async function loadCloud(){const data=await cloud.load();if(data){validateState(data.state);if(dirty&&!confirm('Load the saved league and replace this unsaved draft? Cancel to keep the draft and export it first.')){cloudReady=false;render();return false;}state=data.state;revision=data.revision;dirty=false;}else{revision=0;dirty=true;}cloudReady=true;error='';render();return true;}
function validateState(s){if(s?.version!==1||s.season!=='2026-2027'||s.teams?.length!==18||!Array.isArray(s.bowlers)||!Array.isArray(s.results)||!Array.isArray(s.runs)||!Array.isArray(s.schedule)||!s.adjustments)throw Error('This is not a valid league backup.');const ids=new Set(s.bowlers.map(b=>b.id));for(const t of s.teams)if(!Number.isInteger(t.number)||!Array.isArray(t.players)||t.players.length!==3||t.players.some(id=>!ids.has(id)))throw Error('Invalid team roster in backup.');for(const b of s.bowlers)for(const h of b.history||[])if(!Array.isArray(h.scores)||h.scores.some(v=>!Number.isInteger(v)||v<0||v>300))throw Error('Invalid history score in backup.');}
async function historyFiles(files){for(const file of files){if(file.size>10*1024*1024)throw Error('Each history file must be under 10 MB.');const sheets=file.name.toLowerCase().endsWith('.xlsx')?await readXlsx(await file.arrayBuffer()):[{name:'CSV',rows:parseCSV(await file.text())}];for(const s of sheets){const name=file.name.replace(/\.(xlsx|csv)$/i,'').replace(/\s*history$/i,'').trim(),b=findBowler(state,s.name)||findBowler(state,name);pending.push({type:'history',filename:file.name,sheet:s.name,rows:s.rows,bowlerId:b?.id||'',season:'2025-2026'});}}view='imports';render();}
async function weeklyFile(file){if(file.size>2*1024*1024)throw Error('Weekly CSV must be under 2 MB.');const rows=parseCSV(await file.text());pending.push({type:'weekly',filename:file.name,rows,preview:weeklyPreview(rows,state)});view='imports';render();}
function startSimulation(){if(worker)return;iterations=Number($('#iterations').value);randomSeed=Number($('#random-seed').value);if(!Number.isInteger(iterations)||iterations<1||iterations>100000||!Number.isInteger(randomSeed)||randomSeed<0||randomSeed>4294967295){toast('Enter 1–100,000 simulations and a valid whole-number seed.');return;}const snapshot=structuredClone(state),fingerprint=runFingerprint();progress=0;worker=new Worker(new URL('./simulation-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.error){worker.terminate();worker=null;error=data.error;render();}else if(data.result){worker.terminate();worker=null;const result={...data.result,fingerprint,inputSnapshot:{...snapshot,runs:[]}};state.runs.push(result);state.runs=state.runs.slice(-12);dirty=true;selectedRun=result.id;render();toast(`${fmt(result.iterations)} season simulations complete. Save league to keep this run.`);}else{progress=data.progress;const bar=$('.progress');if(bar){bar.setAttribute('aria-valuenow',Math.round(progress*100));bar.firstElementChild.style.width=progress*100+'%';}}};worker.onerror=()=>{worker.terminate();worker=null;error='The simulation stopped unexpectedly. Try a smaller run.';render();};worker.postMessage({state:snapshot,iterations,seed:randomSeed});render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.view){view=b.dataset.view;render();return;}
 if(b.dataset.period!=null){period=Number(b.dataset.period);render();return;}
 if(b.dataset.player){openPlayer(b.dataset.player);return;}
 if(b.dataset.run){selectedRun=b.dataset.run;render();return;}
 if(b.dataset.resetPlayer){delete state.adjustments[b.dataset.resetPlayer];changed();$('#player-dialog').close();render();return;}
 if(b.dataset.dismissImport!=null){pending.splice(Number(b.dataset.dismissImport),1);render();return;}
 if(b.dataset.importHistory!=null){const i=Number(b.dataset.importHistory),item=pending[i],preview=previewHistory(item);if(preview.issues.length||!item.bowlerId)throw Error('Resolve the import issues first.');const bowler=state.bowlers.find(x=>x.id===item.bowlerId),merged=mergeHistory(bowler.history,preview.sessions);bowler.history=merged.history;state.imports.push({filename:item.filename,at:new Date().toISOString(),description:`${bowler.name}: ${preview.sessions.length-merged.duplicates.length} sessions added, ${merged.duplicates.length} duplicates skipped`});pending.splice(i,1);changed();render();toast('History added. Save league to keep it.');return;}
 if(b.dataset.importWeek!=null){const i=Number(b.dataset.importWeek),item=pending[i],p=weeklyPreview(item.rows,state);if(p.errors.length)throw Error(p.errors[0].message);state.results.push(p.result);state.imports.push({filename:item.filename,at:new Date().toISOString(),description:`Week ${p.result.week}: 54 bowlers, 9 matches`});pending.splice(i,1);changed();render();toast('Week imported. Standings and player ratings updated.');return;}
 switch(b.dataset.action){
 case 'simulate':startSimulation();break;
 case 'cancel-simulation':worker?.terminate();worker=null;render();toast('Simulation cancelled.');break;
 case 'close-player':$('#player-dialog').close();break;
 case 'save':await save();break;
 case 'reload-cloud':await loadCloud();break;
 case 'logout':await cloud.logout();cloudReady=false;render();break;
 case 'export':download(`scratch-classic-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));break;
 case 'undo-week':if(confirm('Remove the latest completed week so it can be corrected and reimported?')){const w=currentWeek(state);state.results=state.results.filter(r=>r.week!==w);if(w%11===0)delete state.thirdWinners[w/11];changed();render();}break;
 case 'weekly-template':{const csv=[['Week','TeamNumber','Bowler','Gm1','Gm2','Gm3','ScoreType'],...state.teams.flatMap(t=>t.players.map(id=>[currentWeek(state)+1,t.number,playerName(id),'','','','actual']))].map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');download('weekly-results-template.csv',csv,'text/csv');break;}
 }
 }catch(err){error=err.message;render();toast(err.message);}});
document.addEventListener('change',async e=>{const t=e.target;try{
 if(t.dataset.fourthImport!=null){const item=pending[Number(t.dataset.fourthImport)];item.corrections??={};item.corrections[t.dataset.fourthRow]=t.value;render();}
 if(t.id==='schedule-week'){selectedWeek=Number(t.value);render();}
 if(t.id==='show-subs'){showSubs=t.checked;render();}
 if(t.dataset.teamName){const name=t.value.trim();if(!name)throw Error('Team name cannot be blank.');state.teams.find(x=>x.number===Number(t.dataset.teamName)).name=name;changed();render();}
 if(t.dataset.importBowler!=null){pending[Number(t.dataset.importBowler)].bowlerId=t.value;render();}
 if(t.dataset.importSeason!=null){pending[Number(t.dataset.importSeason)].season=t.value;render();}
 if(t.dataset.thirdWinner){state.thirdWinners??={};if(t.value)state.thirdWinners[t.dataset.thirdWinner]=Number(t.value);else delete state.thirdWinners[t.dataset.thirdWinner];changed();render();}
 if(t.id==='history-files')await historyFiles(t.files);
 if(t.id==='weekly-file'&&t.files[0])await weeklyFile(t.files[0]);
 if(t.id==='restore-backup'&&t.files[0]){if(t.files[0].size>10*1024*1024)throw Error('Backup exceeds 10 MB.');const next=JSON.parse(await t.files[0].text());validateState(next);if(confirm('Replace the current draft with this backup?')){state=next;changed();render();toast('Backup loaded as an unsaved draft.');}}
 }catch(err){error=err.message;render();}});
document.addEventListener('input',e=>{if(e.target.id==='player-search'){query=e.target.value;const start=e.target.selectionStart;render();$('#player-search').focus();$('#player-search').setSelectionRange(start,start);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{
 if(e.target.id==='login-form'){const d=new FormData(e.target);await cloud.login(d.get('email'),d.get('password'));e.target.reset();cloudReady=false;const loaded=await loadCloud();if(loaded)toast('Connected to your league database.');}
 if(e.target.id==='adjustment-form'){const d=new FormData(e.target),a={delta:Number(d.get('delta')),start:Number(d.get('start')),end:Number(d.get('end'))};if(a.end<a.start)throw Error('End week must be at or after start week.');state.adjustments[e.target.dataset.bowler]=a;changed();$('#player-dialog').close();render();}
 }catch(err){error=err.message;toast(err.message);if(!$('#player-dialog').open)render();}});
document.addEventListener('dragover',e=>{if(e.target.closest('.dropzone'))e.preventDefault();});
document.addEventListener('drop',async e=>{const zone=e.target.closest('.dropzone');if(!zone)return;e.preventDefault();try{if(zone.id==='history-drop')await historyFiles(e.dataTransfer.files);else if(e.dataTransfer.files[0])await weeklyFile(e.dataTransfer.files[0]);}catch(err){error=err.message;render();}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function boot(){try{const response=await fetch('./seed.json');if(!response.ok)throw Error('Could not load the league roster.');state=await response.json();render();if(cloud.email){try{await loadCloud();}catch(e){error=e.message;render();}}}catch(e){$('#app').innerHTML=`<main class="loading"><h1>League unavailable</h1><p>${escape(e.message)}</p><button onclick="location.reload()">Retry</button></main>`;}}
boot();
